:root {
  --bg-page: #0f1117;
  --bg-card: #1a1d27;
  --bg-card-hover: #1f2235;
  --bg-overlay: rgba(0, 0, 0, 0.75);
  --bg-dialog: #1e2130;
  --bg-dialog-header: #181b28;
  --border: #2e3248;
  --border-subtle: #252840;
  --text-primary: #e8eaf0;
  --text-secondary: #8b90a8;
  --text-muted: #555a72;
  --accent-red: #e84545;
  --accent-red-hover: #f05555;
  --accent-red-bg: rgba(232, 69, 69, 0.12);
  --accent-red-border: rgba(232, 69, 69, 0.3);
  --btn-ghost-bg: transparent;
  --btn-ghost-bg-hover: #252840;
  --btn-cancel-bg: #252840;
  --btn-cancel-bg-hover: #2e3350;
  --shadow-dialog: 0 24px 64px rgba(0, 0, 0, 0.6), 0 8px 24px rgba(0, 0, 0, 0.4);
  --radius-card: 12px;
  --radius-dialog: 16px;
  --radius-btn: 8px;
  --transition: 150ms ease;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: var(--bg-page);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 48px 24px;
}

/* ── Page Header ── */
.page-header {
  width: 100%;
  max-width: 960px;
  margin-bottom: 40px;
}

.page-header h1 {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.page-header p {
  margin-top: 6px;
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* ── Image Grid ── */
.image-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
  width: 100%;
  max-width: 960px;
}

/* ── Image Card ── */
.image-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  overflow: hidden;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.image-card:hover {
  border-color: #3a3f5c;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
}

.image-card__thumb {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  display: block;
  background: var(--border-subtle);
}

.image-card__thumb--placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 4 / 3;
  background: linear-gradient(135deg, #1e2235 0%, #252840 100%);
}

.image-card__thumb--placeholder svg {
  opacity: 0.25;
}

.image-card__body {
  padding: 14px 16px 16px;
}

.image-card__name {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-bottom: 4px;
}

.image-card__meta {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-bottom: 14px;
}

.image-card__actions {
  display: flex;
  gap: 8px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 0.8125rem;
  font-weight: 500;
  padding: 7px 14px;
  border-radius: var(--radius-btn);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background var(--transition), color var(--transition), border-color var(--transition);
  text-decoration: none;
  line-height: 1;
}

.btn--ghost {
  background: var(--btn-ghost-bg);
  color: var(--text-secondary);
  border-color: var(--border);
  flex: 1;
}

.btn--ghost:hover {
  background: var(--btn-ghost-bg-hover);
  color: var(--text-primary);
}

.btn--danger-ghost {
  background: var(--btn-ghost-bg);
  color: var(--accent-red);
  border-color: var(--accent-red-border);
  flex: 1;
}

.btn--danger-ghost:hover {
  background: var(--accent-red-bg);
}

/* ── Overlay ── */
.overlay {
  position: fixed;
  inset: 0;
  background: var(--bg-overlay);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 24px;
  opacity: 0;
  visibility: hidden;
  transition: opacity 200ms ease, visibility 200ms ease;
}

.overlay.is-open {
  opacity: 1;
  visibility: visible;
}

/* ── Dialog ── */
.dialog {
  background: var(--bg-dialog);
  border: 1px solid var(--border);
  border-radius: var(--radius-dialog);
  box-shadow: var(--shadow-dialog);
  width: 100%;
  max-width: 420px;
  overflow: hidden;
  transform: scale(0.95) translateY(8px);
  transition: transform 200ms ease;
}

.overlay.is-open .dialog {
  transform: scale(1) translateY(0);
}

.dialog__header {
  background: var(--bg-dialog-header);
  border-bottom: 1px solid var(--border-subtle);
  padding: 20px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.dialog__icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: var(--accent-red-bg);
  border: 1px solid var(--accent-red-border);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--accent-red);
}

.dialog__title-group {
  flex: 1;
}

.dialog__title {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
}

.dialog__subtitle {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 2px;
}

.dialog__close {
  width: 30px;
  height: 30px;
  border-radius: 6px;
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition), color var(--transition);
  flex-shrink: 0;
}

.dialog__close:hover {
  background: var(--btn-ghost-bg-hover);
  color: var(--text-primary);
}

.dialog__body {
  padding: 24px;
}

/* ── Preview Strip ── */
.preview-strip {
  display: flex;
  align-items: center;
  gap: 14px;
  background: var(--bg-dialog-header);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  padding: 12px;
  margin-bottom: 20px;
}

.preview-strip__thumb {
  width: 52px;
  height: 52px;
  border-radius: 6px;
  object-fit: cover;
  flex-shrink: 0;
  background: var(--border-subtle);
}

.preview-strip__thumb--placeholder {
  width: 52px;
  height: 52px;
  border-radius: 6px;
  flex-shrink: 0;
  background: linear-gradient(135deg, #1e2235, #252840);
  display: flex;
  align-items: center;
  justify-content: center;
}

.preview-strip__info {
  min-width: 0;
}

.preview-strip__name {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.preview-strip__meta {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: 2px;
}

/* ── Warning message ── */
.dialog__warning {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 4px;
}

.dialog__warning strong {
  color: var(--text-primary);
}

.dialog__note {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 14px;
  padding: 10px 12px;
  background: var(--accent-red-bg);
  border: 1px solid var(--accent-red-border);
  border-radius: 8px;
  font-size: 0.8rem;
  color: var(--accent-red);
  line-height: 1.5;
}

.dialog__note svg {
  flex-shrink: 0;
  margin-top: 1px;
}

/* ── Dialog Footer ── */
.dialog__footer {
  padding: 0 24px 24px;
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

.btn--cancel {
  background: var(--btn-cancel-bg);
  color: var(--text-secondary);
  border-color: var(--border);
}

.btn--cancel:hover {
  background: var(--btn-cancel-bg-hover);
  color: var(--text-primary);
}

.btn--delete {
  background: var(--accent-red);
  color: #fff;
  border-color: transparent;
}

.btn--delete:hover {
  background: var(--accent-red-hover);
}
