const state = {
  targetImage: null,
};

/* ── Data ── */
const images = [
  { id: 1, name: "mountain-sunset.jpg",  size: "3.2 MB", dims: "4032 × 3024" },
  { id: 2, name: "ocean-waves.jpg",      size: "2.8 MB", dims: "3840 × 2160" },
  { id: 3, name: "forest-path.jpg",      size: "4.1 MB", dims: "4032 × 3024" },
  { id: 4, name: "city-lights.jpg",      size: "1.9 MB", dims: "3840 × 2160" },
  { id: 5, name: "desert-dunes.jpg",     size: "3.5 MB", dims: "4032 × 2688" },
  { id: 6, name: "northern-lights.jpg",  size: "5.0 MB", dims: "5184 × 3456" },
];

/* ── Gradient palettes for placeholder thumbs ── */
const gradients = [
  ["#2d1b4e", "#4a2080"],
  ["#1a3a4a", "#1d6a8a"],
  ["#1a3a28", "#1d7a48"],
  ["#3a2a1a", "#7a5a20"],
  ["#3a1a1a", "#7a2a20"],
  ["#1a1a3a", "#20207a"],
];

/* ── Helpers ── */
function svgPlaceholderIcon() {
  return `<svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor"
    stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
    <rect x="3" y="3" width="18" height="18" rx="2"/>
    <circle cx="8.5" cy="8.5" r="1.5"/>
    <path d="M21 15l-5-5L5 21"/>
  </svg>`;
}

function svgSmallPlaceholder() {
  return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor"
    stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" style="opacity:.4">
    <rect x="3" y="3" width="18" height="18" rx="2"/>
    <circle cx="8.5" cy="8.5" r="1.5"/>
    <path d="M21 15l-5-5L5 21"/>
  </svg>`;
}

/* ── Components ── */
function ImageCard(img, index) {
  const [g1, g2] = gradients[index % gradients.length];
  return `
    <article class="image-card" data-id="${img.id}">
      <div class="image-card__thumb--placeholder" style="background:linear-gradient(135deg,${g1},${g2})">
        ${svgPlaceholderIcon()}
      </div>
      <div class="image-card__body">
        <div class="image-card__name" title="${img.name}">${img.name}</div>
        <div class="image-card__meta">${img.dims} · ${img.size}</div>
        <div class="image-card__actions">
          <button class="btn btn--ghost">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor"
              stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/>
              <circle cx="12" cy="12" r="3"/>
            </svg>
            View
          </button>
          <button class="btn btn--danger-ghost trigger" data-id="${img.id}">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor"
              stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <polyline points="3 6 5 6 21 6"/>
              <path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/>
              <path d="M10 11v6M14 11v6"/>
              <path d="M9 6V4a1 1 0 011-1h4a1 1 0 011 1v2"/>
            </svg>
            Delete
          </button>
        </div>
      </div>
    </article>`;
}

function DeleteDialog() {
  return `
    <div class="overlay" id="deleteOverlay" role="dialog" aria-modal="true"
      aria-labelledby="dialogTitle" aria-describedby="dialogDesc">
      <div class="dialog" id="deleteDialog">
        <div class="dialog__header">
          <div class="dialog__icon" aria-hidden="true">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor"
              stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <polyline points="3 6 5 6 21 6"/>
              <path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/>
              <path d="M10 11v6M14 11v6"/>
              <path d="M9 6V4a1 1 0 011-1h4a1 1 0 011 1v2"/>
            </svg>
          </div>
          <div class="dialog__title-group">
            <div class="dialog__title" id="dialogTitle">Delete Image</div>
            <div class="dialog__subtitle">This action cannot be undone</div>
          </div>
          <button class="dialog__close" id="dialogCloseBtn" aria-label="Close dialog">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor"
              stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
              <line x1="18" y1="6" x2="6" y2="18"/>
              <line x1="6" y1="6" x2="18" y2="18"/>
            </svg>
          </button>
        </div>
        <div class="dialog__body">
          <div class="preview-strip">
            <div class="preview-strip__thumb--placeholder" id="dialogThumb">
              ${svgSmallPlaceholder()}
            </div>
            <div class="preview-strip__info">
              <div class="preview-strip__name" id="dialogImgName">—</div>
              <div class="preview-strip__meta" id="dialogImgMeta">—</div>
            </div>
          </div>
          <p class="dialog__warning" id="dialogDesc">
            Are you sure you want to permanently delete
            <strong id="dialogImgNameInline">this image</strong> from your library?
          </p>
          <div class="dialog__note">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor"
              stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <circle cx="12" cy="12" r="10"/>
              <line x1="12" y1="8" x2="12" y2="12"/>
              <line x1="12" y1="16" x2="12.01" y2="16"/>
            </svg>
            Once deleted, the image cannot be recovered from your library.
          </div>
        </div>
        <div class="dialog__footer">
          <button class="btn btn--cancel" id="dialogCancelBtn">Cancel</button>
          <button class="btn btn--delete" id="dialogDeleteBtn">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor"
              stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <polyline points="3 6 5 6 21 6"/>
              <path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/>
              <path d="M10 11v6M14 11v6"/>
              <path d="M9 6V4a1 1 0 011-1h4a1 1 0 011 1v2"/>
            </svg>
            Delete Image
          </button>
        </div>
      </div>
    </div>`;
}

/* ── Render ── */
function renderApp() {
  const grid = document.getElementById("imageGrid");
  grid.innerHTML = images.map((img, i) => ImageCard(img, i)).join("");

  const app = document.getElementById("app");
  app.insertAdjacentHTML("beforeend", DeleteDialog());

  bindEvents();
}

/* ── Modal logic ── */
function openDialog(imgId) {
  const img = images.find((i) => i.id === imgId);
  if (!img) return;
  state.targetImage = img;

  document.getElementById("dialogImgName").textContent = img.name;
  document.getElementById("dialogImgMeta").textContent = `${img.dims} · ${img.size}`;
  document.getElementById("dialogImgNameInline").textContent = img.name;

  const overlay = document.getElementById("deleteOverlay");
  overlay.classList.add("is-open");
  document.body.style.overflow = "hidden";

  // Focus the cancel button for accessibility
  setTimeout(() => document.getElementById("dialogCancelBtn").focus(), 50);
}

function closeDialog() {
  const overlay = document.getElementById("deleteOverlay");
  overlay.classList.remove("is-open");
  document.body.style.overflow = "";
  state.targetImage = null;
}

function confirmDelete() {
  if (!state.targetImage) return;

  const idx = images.findIndex((i) => i.id === state.targetImage.id);
  if (idx !== -1) images.splice(idx, 1);

  closeDialog();
  renderApp(); // re-render the grid
}

/* ── Event binding ── */
function bindEvents() {
  // Trigger buttons (delete)
  document.querySelectorAll(".trigger").forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = parseInt(btn.dataset.id, 10);
      openDialog(id);
    });
  });

  document.getElementById("dialogCloseBtn").addEventListener("click", closeDialog);
  document.getElementById("dialogCancelBtn").addEventListener("click", closeDialog);
  document.getElementById("dialogDeleteBtn").addEventListener("click", confirmDelete);

  // Close on overlay backdrop click
  document.getElementById("deleteOverlay").addEventListener("click", (e) => {
    if (e.target === e.currentTarget) closeDialog();
  });

  // Close on Escape key
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeDialog();
  }, { once: true });
}

document.addEventListener("DOMContentLoaded", renderApp);
