.page-header {
  width: 100%;
  max-width: 960px;
  margin-bottom: 40px;
}

.page-header h1 {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.page-header p {
  margin-top: 6px;
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* ── Image Grid ── */
.image-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
  width: 100%;
  max-width: 960px;
}

/* ── Image Card ── */
.image-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  overflow: hidden;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.image-card:hover {
  border-color: #3a3f5c;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
}

.image-card__thumb {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  display: block;
  background: var(--border-subtle);
}

.image-card__thumb--placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 4 / 3;
  background: linear-gradient(135deg, #1e2235 0%, #252840 100%);
}

.image-card__thumb--placeholder svg {
  opacity: 0.25;
}

.image-card__body {
  padding: 14px 16px 16px;
}

.image-card__name {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-bottom: 4px;
}

.image-card__meta {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-bottom: 14px;
}

.image-card__actions {
  display: flex;
  gap: 8px;
}

.btn {
  display: inline-flex;
  align-items: center;
