  const img = images.find((i) => i.id === imgId);
  if (!img) return;
  state.targetImage = img;

  document.getElementById("dialogImgName").textContent = img.name;
  document.getElementById("dialogImgMeta").textContent = `${img.dims} · ${img.size}`;
  document.getElementById("dialogImgNameInline").textContent = img.name;

  const overlay = document.getElementById("deleteOverlay");
  overlay.classList.add("is-open");
  document.body.style.overflow = "hidden";

  // Focus the cancel button for accessibility
  setTimeout(() => document.getElementById("dialogCancelBtn").focus(), 50);
}

function closeDialog() {
  const overlay = document.getElementById("deleteOverlay");
  overlay.classList.remove("is-open");
  document.body.style.overflow = "";
  state.targetImage = null;
}

function confirmDelete() {
  if (!state.targetImage) return;

  const idx = images.findIndex((i) => i.id === state.targetImage.id);
  if (idx !== -1) images.splice(idx, 1);

  closeDialog();
  renderApp(); // re-render the grid
}

/* ── Event binding ── */
function bindEvents() {
  // Trigger buttons (delete)
  document.querySelectorAll(".trigger").forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = parseInt(btn.dataset.id, 10);
      openDialog(id);
    });
